const form = $('Form Fields').item.json;
const user = $('Validate User').item.json || {};
const fromOrg = $('Validate Seller').item.json || {};
const toOrg = $('Validate Buyer').item.json || {};
const prod = $('Validate Product').item.json || {};
const sellerInv = $('Get Seller Inventory').item.json || {};
const buyerInv = $('Get Buyer Inventory').item.json || {};

const g = (o, k) => (o[k] === undefined || o[k] === null ? '' : String(o[k]).trim());
const now = new Date().toISOString();
const d = new Date();
const ymd = d.toISOString().slice(0, 10).replace(/-/g, '');
const rand = () => Math.random().toString(36).slice(2, 8).toUpperCase();

const splitId = (v) => String(v || '').split(' - ')[0].trim();
const req = {
  requestId: 'REQ-' + ymd + '-' + rand(), email: g(form, 'User_Email'),
  fromOrgId: splitId(g(form, 'From_Organization')),
  toOrgId: splitId(g(form, 'To_Organization')),
  txnType: g(form, 'Transaction_Type').toUpperCase() || 'SALE',
  productId: splitId(g(form, 'Product')), sku: '',
  qty: Number(g(form, 'Quantity')) || 0,
  requiredDate: g(form, 'Required_Date'), priority: g(form, 'Priority') || 'NORMAL', remarks: g(form, 'Remarks'),
};
req.fromType = String(fromOrg.Type || '').toUpperCase();
req.toType = String(toOrg.Type || '').toUpperCase();

const fail = (type, msg) => {
  const errObj = { Error_ID: 'ERR-' + ymd + '-' + rand(), Timestamp: now, Request_ID: req.requestId, User_Email: req.email,
    Error_Type: type, Error_Message: msg, From_Organization_ID: req.fromOrgId, To_Organization_ID: req.toOrgId,
    Product_ID: req.productId, SKU: req.sku, Quantity: String(req.qty), Workflow_Name: $workflow.name, Node_Name: 'Normalize & Validate', Status: 'OPEN' };
  const errorHtml = [
    '<div style="font-family:Arial,Helvetica,sans-serif;background:#fdf3f3;padding:32px 16px;">',
    '<div style="max-width:560px;margin:0 auto;background:#ffffff;border-radius:14px;overflow:hidden;box-shadow:0 8px 30px rgba(153,27,27,0.12);">',
    '<div style="background:linear-gradient(135deg,#c53030,#9b2c2c);padding:28px 32px;">',
    '<h1 style="margin:0;color:#ffffff;font-size:22px;">Request Could Not Be Processed</h1>',
    '<p style="margin:6px 0 0;color:#fde8e8;font-size:14px;">No inventory or orders were changed.</p></div>',
    '<div style="padding:28px 32px;">',
    '<div style="background:#fdf3f3;border-left:4px solid #c53030;border-radius:8px;padding:16px 20px;margin-bottom:20px;">',
    '<div style="font-size:12px;text-transform:uppercase;letter-spacing:1px;color:#c53030;font-weight:700;">' + type + '</div>',
    '<div style="font-size:15px;color:#2d3748;margin-top:6px;">' + msg + '</div></div>',
    '<table style="width:100%;border-collapse:collapse;font-size:14px;color:#2d3748;">',
    '<tr><td style="padding:8px 0;border-bottom:1px solid #eee;color:#718096;">Request ID</td><td style="padding:8px 0;border-bottom:1px solid #eee;text-align:right;font-weight:700;">' + req.requestId + '</td></tr>',
    '<tr><td style="padding:8px 0;border-bottom:1px solid #eee;color:#718096;">Product</td><td style="padding:8px 0;border-bottom:1px solid #eee;text-align:right;">' + req.productId + '</td></tr>',
    '<tr><td style="padding:8px 0;border-bottom:1px solid #eee;color:#718096;">Quantity</td><td style="padding:8px 0;border-bottom:1px solid #eee;text-align:right;">' + req.qty + '</td></tr>',
    '<tr><td style="padding:8px 0;color:#718096;">Error ID</td><td style="padding:8px 0;text-align:right;">' + errObj.Error_ID + '</td></tr>',
    '</table></div>',
    '<div style="padding:18px 32px;background:#fefafa;font-size:12px;color:#b0a0a0;text-align:center;">Supply Chain Management &bull; Automated by n8n</div>',
    '</div></div>',
  ].join('');
  return [{ json: { valid: false, error: errObj, errorHtml } }];
};

const required = ['User_Email','From_Organization','To_Organization','Product','Quantity'];
for (const f of required) if (!g(form, f)) return fail('MISSING_FIELD', 'Missing required field: ' + f);
if (!req.fromOrgId) return fail('INVALID_SELLER', 'From organization not selected');
if (!req.toOrgId) return fail('INVALID_BUYER', 'To organization not selected');
if (!req.productId) return fail('INVALID_PRODUCT', 'Product not selected');
// Request_ID is generated fresh per submission (REQ-<date>-<random>), so duplicates are not possible by design.
if (!user.Email || String(user.Active).toUpperCase() !== 'TRUE') return fail('INVALID_USER', 'User missing or inactive');
const ROUTES = { MANUFACTURER: 'DISTRIBUTOR', DISTRIBUTOR: 'RETAILER', RETAILER: 'GARAGE' };
if (!fromOrg.Organization_ID || String(fromOrg.Active).toUpperCase() !== 'TRUE') return fail('INVALID_SELLER', 'Seller organization missing or inactive');
if (!toOrg.Organization_ID || String(toOrg.Active).toUpperCase() !== 'TRUE') return fail('INVALID_BUYER', 'Buyer organization missing or inactive');
if (String(fromOrg.Type).toUpperCase() !== req.fromType) return fail('INVALID_ROUTE', 'From_Type does not match seller organization type');
if (String(toOrg.Type).toUpperCase() !== req.toType) return fail('INVALID_ROUTE', 'To_Type does not match buyer organization type');
if (ROUTES[req.fromType] !== req.toType) return fail('INVALID_ROUTE', 'Invalid supply chain route: ' + req.fromType + ' -> ' + req.toType);
if (!prod.Product_ID || String(prod.Active).toUpperCase() !== 'TRUE') return fail('INVALID_PRODUCT', 'Product missing or inactive');
if (req.qty <= 0) return fail('INVALID_QUANTITY', 'Quantity must be greater than 0');

const PRICE_BY_FROM = { MANUFACTURER: 'Distributor_Price', DISTRIBUTOR: 'Retailer_Price', RETAILER: 'Garage_Price' };
const unitPrice = Number(prod[PRICE_BY_FROM[req.fromType]]) || 0;
const taxPct = Number(prod.Tax) || 0;
const subtotal = req.qty * unitPrice;
const taxAmount = subtotal * taxPct / 100;
const total = subtotal + taxAmount;

const sellerQty = Number(sellerInv.Quantity) || 0;
const sellerReserved = Number(sellerInv.Reserved_Qty) || 0;
const sellerAvailable = sellerQty - sellerReserved;
if (sellerAvailable < req.qty) return fail('INSUFFICIENT_STOCK', 'Available ' + sellerAvailable + ' < requested ' + req.qty);

const newSellerQty = sellerQty - req.qty;
const buyerQty = (Number(buyerInv.Quantity) || 0) + req.qty;
const buyerReserved = Number(buyerInv.Reserved_Qty) || 0;
const orderId = 'ORD-' + ymd + '-' + rand();
const txnId = 'TXN-' + ymd + '-' + rand();

const roleSheetIds = $('Role Sheets').item.json || {};
const sheetByType = { MANUFACTURER: roleSheetIds.manufacturerSheetId, DISTRIBUTOR: roleSheetIds.distributorSheetId, RETAILER: roleSheetIds.retailerSheetId, GARAGE: roleSheetIds.garageSheetId };
const sellerSheetId = sheetByType[req.fromType];
const buyerSheetId = sheetByType[req.toType];
if (!sellerSheetId || !buyerSheetId) return fail('INVALID_ROUTE', 'Could not resolve role spreadsheets for ' + req.fromType + ' -> ' + req.toType);

const invRow = (inv, org, type, qty, reserved) => ({
  Inventory_ID: inv.Inventory_ID || 'INV-' + ymd + '-' + rand(),
  Organization_ID: org.Organization_ID, Organization_Name: org.Organization_Name, Organization_Type: type,
  Product_ID: prod.Product_ID, SKU: prod.SKU, Product_Name: prod.Product_Name,
  Quantity: String(qty), Reserved_Qty: String(reserved), Available_Qty: String(qty - reserved),
  Unit_Price: String(unitPrice), Inventory_Value: String(qty * unitPrice), Last_Updated: now,
});

const order = {
  Order_ID: orderId, Request_ID: req.requestId, Timestamp: now, User_Email: req.email,
  From_Organization_ID: fromOrg.Organization_ID, From_Organization: fromOrg.Organization_Name, From_Type: req.fromType,
  To_Organization_ID: toOrg.Organization_ID, To_Organization: toOrg.Organization_Name, To_Type: req.toType,
  Transaction_Type: req.txnType, Product_ID: prod.Product_ID, SKU: prod.SKU, Product_Name: prod.Product_Name,
  Quantity: String(req.qty), Unit: prod.Unit, Unit_Price: String(unitPrice), Tax: String(taxPct),
  Subtotal: String(subtotal), Tax_Amount: String(taxAmount), Total: String(total),
  Required_Date: req.requiredDate, Priority: req.priority, Remarks: req.remarks,
  Order_Status: 'PENDING', Created_At: now, Updated_At: now,
};
const txn = {
  Transaction_ID: txnId, Request_ID: req.requestId, Order_ID: orderId, Timestamp: now, User_Email: req.email,
  Transaction_Type: req.txnType, From_Organization_ID: fromOrg.Organization_ID, From_Organization: fromOrg.Organization_Name,
  From_Type: req.fromType, To_Organization_ID: toOrg.Organization_ID, To_Organization: toOrg.Organization_Name, To_Type: req.toType,
  Product_ID: prod.Product_ID, SKU: prod.SKU, Product_Name: prod.Product_Name, Quantity: String(req.qty),
  Unit_Price: String(unitPrice), Tax: String(taxPct), Total: String(total), Transaction_Status: 'COMPLETED', Created_At: now,
};
const emailHtml = [
  '<div style="font-family:Arial,Helvetica,sans-serif;background:#f4f2fb;padding:32px 16px;">',
  '<div style="max-width:560px;margin:0 auto;background:#ffffff;border-radius:14px;overflow:hidden;box-shadow:0 8px 30px rgba(75,52,145,0.12);">',
  '<div style="background:linear-gradient(135deg,#6b46c1,#553c9a);padding:28px 32px;">',
  '<h1 style="margin:0;color:#ffffff;font-size:22px;">Order Confirmed</h1>',
  '<p style="margin:6px 0 0;color:#e6defa;font-size:14px;">Your supply chain transaction was processed successfully.</p></div>',
  '<div style="padding:28px 32px;">',
  '<table style="width:100%;border-collapse:collapse;font-size:14px;color:#2d3748;">',
  '<tr><td style="padding:10px 0;border-bottom:1px solid #eee;color:#718096;">Order ID</td><td style="padding:10px 0;border-bottom:1px solid #eee;text-align:right;font-weight:700;">' + orderId + '</td></tr>',
  '<tr><td style="padding:10px 0;border-bottom:1px solid #eee;color:#718096;">Product</td><td style="padding:10px 0;border-bottom:1px solid #eee;text-align:right;font-weight:700;">' + prod.Product_Name + '</td></tr>',
  '<tr><td style="padding:10px 0;border-bottom:1px solid #eee;color:#718096;">Route</td><td style="padding:10px 0;border-bottom:1px solid #eee;text-align:right;">' + fromOrg.Organization_Name + ' &rarr; ' + toOrg.Organization_Name + '</td></tr>',
  '<tr><td style="padding:10px 0;border-bottom:1px solid #eee;color:#718096;">Quantity</td><td style="padding:10px 0;border-bottom:1px solid #eee;text-align:right;">' + req.qty + '</td></tr>',
  '<tr><td style="padding:10px 0;border-bottom:1px solid #eee;color:#718096;">Unit Price</td><td style="padding:10px 0;border-bottom:1px solid #eee;text-align:right;">Rs. ' + unitPrice + '</td></tr>',
  '<tr><td style="padding:10px 0;border-bottom:1px solid #eee;color:#718096;">Tax (' + taxPct + '%)</td><td style="padding:10px 0;border-bottom:1px solid #eee;text-align:right;">Rs. ' + taxAmount + '</td></tr>',
  '<tr><td style="padding:14px 0;font-weight:800;font-size:16px;">Total</td><td style="padding:14px 0;text-align:right;font-weight:800;font-size:20px;color:#6b46c1;">Rs. ' + total + '</td></tr>',
  '</table>',
  '<div style="margin-top:16px;background:#f4f2fb;border-radius:10px;padding:14px 18px;font-size:13px;color:#553c9a;">',
  '<strong>Transaction:</strong> ' + txnId + '<br><strong>Request:</strong> ' + req.requestId + '</div></div>',
  '<div style="padding:18px 32px;background:#faf9fe;font-size:12px;color:#a0aec0;text-align:center;">Supply Chain Management &bull; Automated by n8n</div>',
  '</div></div>',
].join('');
return [{ json: {
  valid: true, email: req.email, orderId, txnId, emailHtml, sellerSheetId, buyerSheetId,
  order, orderCompleted: Object.assign({}, order, { Order_Status: 'COMPLETED', Updated_At: now }),
  txn, sellerInv: invRow(sellerInv, fromOrg, req.fromType, newSellerQty, sellerReserved),
  buyerInv: invRow(buyerInv, toOrg, req.toType, buyerQty, buyerReserved),
} }];

