const f = $('Master Data Form').item.json;
const g = (k) => (f[k] === undefined || f[k] === null ? '' : String(f[k]).trim());
const now = new Date().toISOString();
const ymd = now.slice(0, 10).replace(/-/g, '');
const rand = () => Math.random().toString(36).slice(2, 8).toUpperCase();
const splitId = (v) => String(v || '').split(' - ')[0].trim();
const type = g('Entity_Type').toUpperCase();

if (type === 'USER') {
  const orgId = splitId(g('Organization'));
  const orgName = g('Organization').split(' - ').slice(1).join(' - ');
  return [{ json: {
    target: 'USERS',
    row: { User_ID: 'U-' + ymd + '-' + rand(), Name: g('Name'), Email: g('Email'),
      Role: g('Role') || 'DISTRIBUTOR', Organization_ID: orgId, Organization_Name: orgName,
      Organization_Type: '', Active: 'TRUE', Created_At: now, Updated_At: now },
  } }];
}
if (type === 'PRODUCT') {
  return [{ json: {
    target: 'PRODUCTS',
    row: { Product_ID: 'P-' + ymd + '-' + rand(), SKU: g('SKU'), Product_Name: g('Name'),
      Category: g('Category'), Unit: g('Unit') || 'pcs', Base_Cost: g('Base_Cost') || '0',
      Manufacturer_Price: g('Manufacturer_Price') || '0', Distributor_Price: g('Distributor_Price') || '0',
      Retailer_Price: g('Retailer_Price') || '0', Garage_Price: g('Garage_Price') || '0',
      MRP: g('MRP') || '0', Tax: g('Tax') || '0', Reorder_Level: g('Reorder_Level') || '0',
      Active: 'TRUE', Updated_At: now },
  } }];
}
if (type === 'ORGANIZATION') {
  const parent = g('Parent_Organization');
  return [{ json: {
    target: 'ORGANIZATIONS',
    row: { Organization_ID: 'ORG-' + ymd + '-' + rand(), Organization_Name: g('Name'),
      Type: g('Org_Type') || 'DISTRIBUTOR', Parent_Organization_ID: parent === 'None' ? '' : splitId(parent),
      Contact: g('Contact'), Phone: g('Phone'), Email: g('Email'), Location: g('Location'),
      Active: 'TRUE', Created_At: now, Updated_At: now },
  } }];
}
return [{ json: { target: 'INVALID', row: { error: 'Unknown Entity_Type: ' + type } } }];

const email = $('My Records Form').item.json.Email;
const orders = $('Get My Orders').all().map(i => i.json).filter(o => Object.keys(o).length);
const txns = $('Get My Transactions').all().map(i => i.json).filter(o => Object.keys(o).length);

const money = (v) => { const n = Number(v); return isNaN(n) ? String(v || '') : '$' + n.toFixed(2); };
const row = (cells, header) => '<tr>' + cells.map(c => '<' + (header ? 'th' : 'td') + ' style="padding:8px 10px;border-bottom:1px solid #e5e0f2;text-align:left;font-size:13px;color:' + (header ? '#6b46c1' : '#2d3748') + ';">' + (c == null ? '' : c) + '</' + (header ? 'th' : 'td') + '>').join('') + '</tr>';

let html = '<div style="font-family:Arial,Helvetica,sans-serif;background:#f4f2fb;padding:32px 16px;">' +
  '<div style="max-width:720px;margin:0 auto;background:#fff;border-radius:14px;overflow:hidden;box-shadow:0 8px 30px rgba(75,52,145,0.12);">' +
  '<div style="background:linear-gradient(135deg,#6b46c1,#553c9a);padding:28px 32px;">' +
  '<h1 style="margin:0;color:#fff;font-size:22px;">Your Supply Chain Records</h1>' +
  '<p style="margin:6px 0 0;color:#e3dbff;font-size:14px;">Live report for ' + email + ' - ' + new Date().toUTCString() + '</p></div>' +
  '<div style="padding:28px 32px;">';

html += '<h2 style="font-size:16px;color:#2d1b5e;">Orders (' + orders.length + ')</h2>';
if (!orders.length) html += '<p style="color:#718096;font-size:14px;">No orders found for this email.</p>';
else {
  html += '<table style="width:100%;border-collapse:collapse;">' +
    row(['Order ID','Date','From','To','Product','Qty','Total','Status'], true);
  for (const o of orders) html += row([o.Order_ID, String(o.Created_At||o.Timestamp||'').slice(0,10), o.From_Organization, o.To_Organization, o.Product_Name, o.Quantity, money(o.Total), o.Order_Status]);
  html += '</table>';
}

html += '<h2 style="font-size:16px;color:#2d1b5e;margin-top:28px;">Transactions (' + txns.length + ')</h2>';
if (!txns.length) html += '<p style="color:#718096;font-size:14px;">No transactions found for this email.</p>';
else {
  html += '<table style="width:100%;border-collapse:collapse;">' +
    row(['Transaction ID','Date','Type','From','To','Product','Qty','Total'], true);
  for (const t of txns) html += row([t.Transaction_ID, String(t.Created_At||t.Timestamp||'').slice(0,10), t.Transaction_Type, t.From_Organization, t.To_Organization, t.Product_Name, t.Quantity, money(t.Total)]);
  html += '</table>';
}

html += '</div><div style="padding:18px 32px;background:#faf8ff;font-size:12px;color:#a89cc9;text-align:center;">Supply Chain Management - Automated by n8n</div></div></div>';

return [{ json: { email, orderCount: orders.length, txnCount: txns.length, html } }];

const tag = (rows) => rows.map(i => i.json).filter(o => Object.keys(o).length);
const manufacturer = tag($('Get Manufacturer Responses').all());
const distributor = tag($('Get Distributor Responses').all());
const retailer = tag($('Get Retailer Responses').all());
const garage = tag($('Get Garage Responses').all());

return [{ json: {
  generatedAt: new Date().toUTCString(),
  counts: {
    manufacturer: manufacturer.length,
    distributor: distributor.length,
    retailer: retailer.length,
    garage: garage.length,
    total: manufacturer.length + distributor.length + retailer.length + garage.length,
  },
  roles: { manufacturer, distributor, retailer, garage },
} }];
